const ELEMENT_NAME="nikas-rooms-v11";
const UI_VERSION="11.0.0";
const ACTIVE_LABEL="v_ekspluatatsii";
const CLIMATE_LABEL="datchik_klimata_pomeshcheniia";
const EXCLUDED_LABELS=new Set(["rezerv","na_obsluzhivanii","trebuet_zameny","vyvedeno_iz_ekspluatatsii"]);
const BAD=new Set(["unknown","unavailable","none","null",""]);
const ROOMS=[["bathroom","01","Ванная","mdi:bathtub-outline",2],["bedroom","02","Спальня","mdi:bed-outline",2],["wardrobe","03","Гардероб","mdi:hanger",2],["sasha","04","У Саши","mdi:account",2],["ilya","05","У Ильи","mdi:account-outline",2],["stairs","06","Лестница","mdi:stairs",2],["corridor","07","Коридор","mdi:door-open",2],["hall","08","Холл","mdi:sofa-outline",2],["boiler","09","Котельная","mdi:water-boiler",1],["kitchen","10","Кухня","mdi:fridge-outline",1],["dining","11.1","Столовая","mdi:table-chair",1],["living","11.2","Гостиная","mdi:sofa",1],["toilet","12","Туалет","mdi:toilet",1],["vestibule","13","Тамбур","mdi:door-closed-lock",1],["veranda","14","Веранда","mdi:home-outline",1],["garage","15","Гараж","mdi:garage",1],["attic","16","Чердак","mdi:home-roof",0],["greenhouse","17","Теплица","mdi:greenhouse",0]].map(([slug,no,name,icon,floor])=>({slug,no,name,icon,floor}));
function norm(v){return String(v??"").trim().toLocaleLowerCase("ru-RU").replace(/ё/g,"е").replace(/\s+/g," ")}
function normArea(v){return norm(v).replace(/^\d+(?:[.,]\d+)?\s*(?:[-–—.:)]\s*)?/,"").trim()}
function labelsOf(x){const v=x?.labels;if(!v)return[];if(Array.isArray(v))return v;if(v instanceof Set)return[...v];if(typeof v==="object")return Object.keys(v).filter(k=>v[k]);return[]}
function operational(x){const s=new Set(labelsOf(x));return s.has(ACTIVE_LABEL)&&![...EXCLUDED_LABELS].some(id=>s.has(id))}
function domain(id){return String(id||"").split(".")[0]}
function stateClass(e,hass){return e?.device_class||hass?.states?.[e?.entity_id]?.attributes?.device_class||""}
function titleOfEntity(e,hass){return e?.name||hass?.states?.[e?.entity_id]?.attributes?.friendly_name||e?.original_name||e?.entity_id||"Сущность"}
function titleOfDevice(d){return d?.name_by_user||d?.name||d?.model||"Устройство"}
function goodState(s){return !BAD.has(norm(s))}
function esc(v){return String(v??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;")}
class NikasRoomsV11 extends HTMLElement{
constructor(){super();this.attachShadow({mode:"open"});this._hass=null;this._registries=null;this._rooms=[];this._loading=false;this._mounted=false;this._routeKey="";this._fitFrame=null;this._onLocation=()=>this.renderRoute();this._onResize=()=>this.scheduleFit()}
set panel(v){this._panel=v}
set hass(v){const first=!this._hass;this._hass=v;if(first)this.loadRegistries();else this.patchStates()}
connectedCallback(){window.addEventListener("location-changed",this._onLocation);window.addEventListener("popstate",this._onLocation);window.addEventListener("resize",this._onResize,{passive:true});window.visualViewport?.addEventListener?.("resize",this._onResize,{passive:true});this.mountShell();this.scheduleFit()}
disconnectedCallback(){window.removeEventListener("location-changed",this._onLocation);window.removeEventListener("popstate",this._onLocation);window.removeEventListener("resize",this._onResize);window.visualViewport?.removeEventListener?.("resize",this._onResize);if(this._fitFrame!==null)cancelAnimationFrame(this._fitFrame)}
mountShell(){if(this._mounted)return;this._mounted=true;this.shadowRoot.innerHTML=`<style>${this.styles()}</style><div class="viewport"><div class="canvas" id="canvas"><div class="loading">Загрузка помещений…</div></div></div>`}
async loadRegistries(){if(this._loading||!this._hass?.callWS)return;this._loading=true;try{const [areas,devices,entities,labels]=await Promise.all([this._hass.callWS({type:"config/area_registry/list"}),this._hass.callWS({type:"config/device_registry/list"}),this._hass.callWS({type:"config/entity_registry/list"}),this._hass.callWS({type:"config/label_registry/list"}).catch(()=>[])]);this._registries={areas,devices,entities,labels};this.buildRooms();this.renderRoute(true)}catch(err){console.warn("[NikaS Rooms v11] registry load failed",err);const c=this.shadowRoot?.getElementById("canvas");if(c)c.innerHTML='<div class="loading">Не удалось прочитать реестр Home Assistant</div>'}finally{this._loading=false}}
buildRooms(){const{areas,devices,entities,labels}=this._registries;const labelMap=new Map(labels.map(l=>[l.label_id,l.name||l.label_id]));this._rooms=ROOMS.map(def=>{const area=areas.find(a=>norm(a.name)===norm(def.name)||normArea(a.name)===norm(def.name)||norm(a.area_id)===norm(def.name));if(!area)return{...def,area:null,devices:[],entities:[],labelMap};const roomDevices=devices.filter(d=>d.area_id===area.area_id&&!d.disabled_by&&operational(d));const ids=new Set(roomDevices.map(d=>d.id));const roomEntities=entities.filter(e=>!e.disabled_by&&!e.hidden_by&&((e.area_id===area.area_id)||(!e.area_id&&e.device_id&&ids.has(e.device_id))));return{...def,area,devices:roomDevices,entities:roomEntities,labelMap}})}
route(){const p=location.pathname.split("/").filter(Boolean);if(p[0]!=="dashboard-rooms")return{kind:"overview"};if(p[1]?.startsWith("room-")){const slug=p[1].slice(5);return{kind:p[2]==="diagnostics"?"diagnostics":"room",slug}}return{kind:"overview"}}
routeKey(r){return`${r.kind}:${r.slug||""}`}
nav(path){history.pushState(null,"",path);window.dispatchEvent(new Event("location-changed"))}
room(slug){return this._rooms.find(r=>r.slug===slug)}
entityState(e){return this._hass?.states?.[e.entity_id]}
summary(room){if(!room?.area)return{text:"Нет данных",tone:"grey"};const es=room.entities.filter(e=>domain(e.entity_id)==="binary_sensor"&&["door","window","opening","garage_door","motion","occupancy","presence"].includes(stateClass(e,this._hass)));let open=0,motion=0,bad=0;for(const e of es){const s=this.entityState(e)?.state,c=stateClass(e,this._hass);if(!goodState(s)){bad++;continue}if(s==="on"&&["door","window","opening","garage_door"].includes(c))open++;if(s==="on"&&["motion","occupancy","presence"].includes(c))motion++}if(open)return{text:`Открыто ${open}`,tone:"yellow"};if(motion)return{text:`Активность ${motion}`,tone:"blue"};if(bad)return{text:"Требует внимания",tone:"orange"};return{text:"Спокойно",tone:"green"}}
formatEntity(e){const st=this.entityState(e);if(!st||!goodState(st.state))return"Нет данных";const s=st.state,unit=st.attributes?.unit_of_measurement||"",c=stateClass(e,this._hass);if(domain(e.entity_id)==="binary_sensor"){if(["door","window","opening","garage_door"].includes(c))return s==="on"?"Открыто":"Закрыто";if(["motion","occupancy","presence"].includes(c))return s==="on"?"Обнаружено":"Не обнаружено"}return`${s}${unit?` ${unit}`:""}`}
climateDevices(room){return room.devices.filter(d=>labelsOf(d).includes(CLIMATE_LABEL))}
entitiesForDevices(room,ds){const ids=new Set(ds.map(d=>d.id));return room.entities.filter(e=>e.device_id&&ids.has(e.device_id))}
climatePairs(room,ds){const es=this.entitiesForDevices(room,ds);return{temp:es.filter(e=>stateClass(e,this._hass)==="temperature"),hum:es.filter(e=>stateClass(e,this._hass)==="humidity")}}
renderRoute(force=false){if(!this._registries)return;const r=this.route(),key=this.routeKey(r);if(!force&&key===this._routeKey){this.patchStates();return}this._routeKey=key;const room=r.slug?this.room(r.slug):null,canvas=this.shadowRoot.getElementById("canvas");canvas.innerHTML=r.kind==="overview"?this.overviewMarkup():r.kind==="diagnostics"?this.diagnosticsMarkup(room):this.roomMarkup(room);canvas.className=`canvas ${r.kind}`;this.bindView(room);this.scheduleFit()}
overviewMarkup(){const group=(floor,label,icon)=>`<section class="floor"><h2><ha-icon icon="${icon}"></ha-icon>${label}</h2><div class="room-grid">${this._rooms.filter(r=>r.floor===floor).map(r=>this.roomCard(r)).join("")}</div></section>`;return`<div class="overview">${group(2,"2 этаж","mdi:home-floor-2")}${group(1,"1 этаж","mdi:home-floor-1")}${group(0,"Технические помещения","mdi:tools")}</div>`}
roomCard(room){const s=this.summary(room);return`<button class="room-card tone-${s.tone}" data-room="${room.slug}" data-summary-room="${room.slug}"><ha-icon icon="${room.icon}"></ha-icon><span><b>${esc(room.name)} [${room.no}]</b><small data-summary-text>${esc(s.text)}</small></span></button>`}
section(title,icon,entities){if(!entities.length)return"";return`<section class="section"><h2><ha-icon icon="${icon}"></ha-icon>${title}</h2><div class="entity-grid">${entities.map(e=>`<button class="entity" data-entity="${e.entity_id}"><span>${esc(titleOfEntity(e,this._hass))}</span><b data-value="${e.entity_id}">${esc(this.formatEntity(e))}</b></button>`).join("")}</div></section>`}
extraClimate(room,primary){const primaryIds=new Set(primary.map(d=>d.id));return room.devices.filter(d=>!primaryIds.has(d.id)).map(d=>{const p=this.climatePairs(room,[d]);if(!p.temp.length&&!p.hum.length)return"";return`<div class="sensor-card"><b>${esc(titleOfDevice(d))}</b>${[...p.temp,...p.hum].map(e=>`<button data-entity="${e.entity_id}"><span>${esc(titleOfEntity(e,this._hass))}</span><strong data-value="${e.entity_id}">${esc(this.formatEntity(e))}</strong></button>`).join("")}</div>`}).join("")}
roomMarkup(room){if(!room?.area)return'<div class="loading">Помещение не найдено в реестре HA</div>';const primary=this.climateDevices(room),cp=this.climatePairs(room,primary),activity=room.entities.filter(e=>["motion","occupancy","presence","illuminance"].includes(stateClass(e,this._hass))),security=room.entities.filter(e=>["door","window","opening","garage_door"].includes(stateClass(e,this._hass))),cameras=room.entities.filter(e=>domain(e.entity_id)==="camera"),extra=this.extraClimate(room,primary);return`<div class="room-view">${this.section("Климат","mdi:thermometer",[...cp.temp,...cp.hum])}${extra?`<section class="section"><h2><ha-icon icon="mdi:thermometer-lines"></ha-icon>Дополнительные климатические датчики</h2><div class="sensor-grid">${extra}</div></section>`:""}${this.section("Активность","mdi:motion-sensor",activity)}${this.section("Безопасность","mdi:shield-home",security)}${this.section("Камеры","mdi:cctv",cameras)}<button class="diagnostics" id="diagnostics">Диагностика</button></div>`}
diagnosticsMarkup(room){if(!room?.area)return'<div class="loading">Помещение не найдено</div>';const devices=room.devices.map(d=>`<article class="device"><h3>${esc(titleOfDevice(d))}</h3><div class="chips">${labelsOf(d).map(id=>`<span>${esc(room.labelMap.get(id)||id)}</span>`).join("")}</div>${room.entities.filter(e=>e.device_id===d.id).map(e=>`<button data-entity="${e.entity_id}"><span>${esc(titleOfEntity(e,this._hass))}</span><b data-value="${e.entity_id}">${esc(this.formatEntity(e))}</b></button>`).join("")}</article>`).join("");return`<div class="diag"><button class="back-plaque" id="back-room">${esc(room.name)}</button><section class="diag-card"><h2>Оборудование</h2><p>${esc(room.area.name)} · ${room.devices.length} поз.</p><div class="devices">${devices||'<div class="loading">Нет оборудования</div>'}</div></section></div>`}
bindView(room){this.shadowRoot.querySelectorAll("[data-room]").forEach(b=>b.onclick=()=>this.nav(`/dashboard-rooms/room-${b.dataset.room}`));this.shadowRoot.querySelectorAll("[data-entity]").forEach(b=>b.onclick=()=>this.dispatchEvent(new CustomEvent("hass-more-info",{bubbles:true,composed:true,detail:{entityId:b.dataset.entity}})));this.shadowRoot.getElementById("diagnostics")?.addEventListener("click",()=>this.nav(`/dashboard-rooms/room-${room.slug}/diagnostics`));this.shadowRoot.getElementById("back-room")?.addEventListener("click",()=>this.nav(`/dashboard-rooms/room-${room.slug}`))}
patchStates(){if(!this._registries||!this.isConnected)return;const all=this._rooms.flatMap(r=>r.entities),byId=new Map(all.map(e=>[e.entity_id,e]));for(const n of this.shadowRoot.querySelectorAll("[data-value]")){const e=byId.get(n.dataset.value);if(!e)continue;const v=this.formatEntity(e);if(n.textContent!==v)n.textContent=v}for(const n of this.shadowRoot.querySelectorAll("[data-summary-room]")){const room=this.room(n.dataset.summaryRoom),s=this.summary(room),text=n.querySelector("[data-summary-text]");if(text&&text.textContent!==s.text)text.textContent=s.text;for(const t of["yellow","blue","orange","green","grey"])n.classList.toggle(`tone-${t}`,t===s.tone)}}
scheduleFit(){if(this._fitFrame!==null)cancelAnimationFrame(this._fitFrame);this._fitFrame=requestAnimationFrame(()=>{this._fitFrame=null;this.fitViewport()})}
fitViewport(){const host=this.shadowRoot?.querySelector(".viewport"),header=document.getElementById("nikas-generated-subpanel-header"),bar=document.getElementById("nikas-global-tabbar");if(!host)return;const top=header?.getBoundingClientRect?.().bottom??0,bottom=bar?.getBoundingClientRect?.().top??window.innerHeight;if(bottom>top){host.style.top=`${Math.round(top)}px`;host.style.height=`${Math.round(bottom-top)}px`}}
styles(){return`:host{position:fixed;inset:0;z-index:1;pointer-events:none;color:var(--primary-text-color,#111);font-family:var(--paper-font-body1_-_font-family,Arial,sans-serif)}*{box-sizing:border-box}.viewport{position:fixed;left:0;right:0;top:70px;height:calc(100dvh - 140px);overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;pointer-events:auto;background:var(--primary-background-color,#f7f7f7);-webkit-overflow-scrolling:touch}.canvas{min-height:100%;padding:10px 8px 14px}.loading{padding:24px;text-align:center;color:var(--secondary-text-color,#666)}.overview{min-height:100%;display:flex;flex-direction:column;justify-content:space-between;gap:6px}.floor h2{height:22px;margin:0 0 4px;display:flex;align-items:center;gap:7px;font-size:16px;font-weight:650}.floor h2 ha-icon{--mdc-icon-size:20px}.room-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px 7px}.room-card{min-height:46px;border:1px solid var(--divider-color,#ddd);border-radius:14px;background:var(--card-background-color,#fff);padding:5px 9px;display:grid;grid-template-columns:32px minmax(0,1fr);gap:5px;align-items:center;text-align:left;color:inherit}.room-card>ha-icon{--mdc-icon-size:25px;color:var(--primary-color,#2196f3)}.room-card b,.room-card small{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.room-card b{font-size:14px}.room-card small{font-size:12px;margin-top:1px}.tone-yellow>ha-icon{color:#f2c400}.tone-orange>ha-icon{color:#fb8c00}.tone-green>ha-icon{color:#2dbd65}.tone-blue>ha-icon{color:#2196f3}.tone-grey>ha-icon{color:#999}.section{margin:0 0 13px}.section h2{display:flex;align-items:center;gap:8px;margin:0 0 7px;font-size:19px}.section h2 ha-icon{--mdc-icon-size:23px}.entity-grid,.sensor-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.entity,.sensor-card{min-height:52px;border:1px solid var(--divider-color,#ddd);border-radius:14px;background:var(--card-background-color,#fff);color:inherit;padding:9px 10px}.entity{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:8px;text-align:left}.entity span,.sensor-card button span,.device button span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.entity b{white-space:nowrap}.sensor-card>b{display:block;margin-bottom:5px}.sensor-card button,.device button{width:100%;border:0;border-top:1px solid var(--divider-color,#ddd);background:transparent;color:inherit;padding:7px 0;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;text-align:left}.diagnostics,.back-plaque{width:100%;min-height:52px;border:1px solid var(--divider-color,#ddd);border-radius:16px;background:var(--card-background-color,#fff);font:inherit;font-size:17px;font-weight:800;color:inherit}.back-plaque{margin-bottom:10px}.diag-card{background:var(--card-background-color,#fff);border:1px solid var(--divider-color,#ddd);border-radius:18px;padding:13px}.diag-card h2{margin:0;font-size:20px}.diag-card p{margin:3px 0 10px;color:var(--secondary-text-color,#666)}.devices{display:grid;gap:9px}.device{background:var(--secondary-background-color,#eee);border:1px solid var(--divider-color,#ddd);border-radius:14px;padding:10px}.device h3{margin:0 0 7px;font-size:16px}.chips{display:flex;gap:5px;flex-wrap:wrap;margin-bottom:5px}.chips span{padding:3px 6px;border-radius:999px;background:var(--card-background-color,#fff);font-size:12px;color:var(--secondary-text-color,#666)}@media(max-height:780px){.canvas{padding-top:7px}.room-card{min-height:43px}.room-card b{font-size:13px}.floor h2{height:20px;margin-bottom:2px}.overview{gap:3px}}@media(min-width:850px){.canvas{width:min(900px,100%);margin:0 auto}}`}
}
if(!customElements.get(ELEMENT_NAME))customElements.define(ELEMENT_NAME,NikasRoomsV11);
